function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#e08a72");
  let grassColor = "#8aa461";
  fill(grassColor);
  brush.fillTexture(1, 0);
  brush.fill(grassColor, 1);
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.endShape(true);

  let peaksColor = "#e87e40";
  brush.fillTexture(0.5, 0);
  brush.fill(peaksColor, 1);
  brush.circle(200, 0, 100);
  brush.fillTexture(1, 1);
  brush.fill(peaksColor, 0);
  brush.circle(100, 0, 80);
  brush.circle(300, 0, 70);
  brush.circle(400, 0, 100);

  let cloudColor = "#e5e6ff";
  fill(cloudColor);
  brush.vertex(0, 200);
  brush.vertex(400, 200);
  brush.endShape(true);
  brush.vertex(0, 0);
  brush.vertex(0, 200);
  brush.endShape(true);

  let starColor = "#f8f9fe";
  fill(starColor);
  brush.vertex(0, 200);
  brush.vertex(0, 350);
  brush.vertex(200, 200);
  brush.endShape(true);
}
