function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  //Horizon at 200 units long, rain falling into the sunset
  drawVerticalStripe("#e6b033", 200);

  //The land to the left of the ocean 
  strokeWeight(5);
  stroke("#88a2a2");
  pathThickness = 1;
  drawPathBGP("#0b1a27", 200);

  //The background has undulating hills
  drawWaves("#0d302f", 60, 40);

  //Ash falls on the hills
  strokeWeight(10);
  stroke("#2f4e60");
  for (let x = 150; x <= 240; x++) {
    let t = 200 + (x - 150) * 4;
    if (t > 400) t = 400;
    drawPerpendicularLine(x, t, "#e94725");
    drawPerpendicularLine(x, t - 2, "#d72013");
    drawPerpendicularLine(x, t - 15, "#43435c");
    drawPerpendicularLine(x, t - 30, "#3a221b");
    drawPerpendicularLine(x, t - 45, "#03303a");
  }

  //Wind adds some irregularities in the waves
  strokeWidth(2);
  stroke("#806c5a");
  drawWaves("#0d302f", 60, 80);

  //To make the sea blue, don't add nothing
  drawVerticalStripe("#33334e", 120);

  //Some sky right at the horizon
  drawVerticalStripe("#002233", 200);

  //A setting sun comes down the sky
  drawSunflower("#c44e1b", 200);

  //Adding bling
  drawStars("#c89a39", 200);
  drawStars("#385567", 40);
}

