function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Create the sky color
  fill("#f4efe4");
  brush.fill("#f4efe4", 1);
  brush.beginShape();
  brush.vertex(200, 0);
  brush.vertex(400, 0);
  brush.vertex(200, 200);
  brush.endShape(true);

  // Create the mountain range
  for (let i = 0; i < 25; i++) {
    fill("#606854");
    brush.fill("#606854", 1);
    brush.beginShape();
    brush.vertex(i * 20, 400);
    brush.vertex(i * 20 + 100, 400);
    brush.vertex(i * 20 + 50, 300);
    brush.endShape(true);
  }

  // Create the hills
  fill("#3f3f3f");
  brush.fill("#3f3f3f", 1);
  brush.beginShape();
  brush.vertex(200, 100);
  brush.vertex(400, 100);
  brush.vertex(200, 200);
  brush.endShape(true);

  // Create the sun
  fill("#ff9933");
  brush.fill("#ff9933", 1);
  brush.beginShape();
  brush.vertex(160, 160);
  brush.vertex(160, 200);
  brush.vertex(240, 200);
  brush.endShape(true);
}
