const TURBID = 84;
function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(3);
  noLoop();
}
function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  strokeWeight(3);
  stroke(0, SATURATE, BRIGHTNESS, TURBID);
  push();
  brush.fill("#e08a72", 180);
  brush.fillBleed(1);
  brush.circle(200, 200, 200);
