function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // 1st Brush - Sky - Blue
  brush.fill("#73c9e0", 30);
  brush.circle(0, 400, 250);  // 0, 400, radius 250 
  brush.fill("#2c6e8b", 30);
  brush.circle(0, 150, 250);
  brush.fill("#5b81a3", 50); 
  brush.circle(100, 0, 250);
  brush.fill("#4b6c77", 50); 
  brush.circle(-100, 0, 250);

  // 2nd Brush - Grass - Green
  brush.fill("#50ae40", 50);
  brush.beginShape();
  brush.vertex(-100, -200);
  brush.vertex(0, -200);
  brush.vertex(100, -200);
  brush.endShape();

  // 3rd Brush - Ant Hill (Fastret) - Brown
  brush.fill("#995500", 50);
  brush.beginShape();
  brush.vertex(150, -50);
  brush.vertex(-150, 0);
  brush.vertex(0, 50);
  brush.endShape();
  brush.fill("#d48044", 50); 
  brush.beginShape();
  brush.vertex(-150, 50);
  brush.vertex(0, 0);
  brush.vertex(150, 50);
  brush.endShape(true);

  // 4th Brush - Lake - Blue
  brush.fill("#009d60", 60);
  brush.beginShape();
  brush.vertex(-50, -50);
  brush.vertex(0, 50);
  brush.vertex(50, -50);
  brush.endShape();
  brush.fill("#00804b", 60);
  brush.beginShape();
  brush.vertex(-50, 50);
  brush.vertex(0, 0);
  brush.vertex(50, 50);
  brush.endShape(true);
}
